#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkCmdWaitEventsRequest {
    pub command_buffer: VkCommandBuffer,
    pub event_count: u32,
    pub p_events: Vec<VkEvent>,
    pub src_stage_mask: VkPipelineStageFlags,
    pub dst_stage_mask: VkPipelineStageFlags,
    pub memory_barrier_count: u32,
    pub p_memory_barriers: Vec<VkMemoryBarrier>,
    pub buffer_memory_barrier_count: u32,
    pub p_buffer_memory_barriers: Vec<VkBufferMemoryBarrier>,
    pub image_memory_barrier_count: u32,
    pub p_image_memory_barriers: Vec<VkImageMemoryBarrier>,
}

impl VkCmdWaitEventsRequest {
    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let command_buffer = VkCommandBuffer::decode(dec)?;
        let event_count = dec.read_u32()?;
        let p_events_sz = dec.read_array_size_unchecked()?;
        let mut p_events = Vec::with_capacity(p_events_sz as usize);
        for _ in 0..p_events_sz { p_events.push(VkEvent::decode(dec)?); }
        let src_stage_mask = dec.read_u32()?;
        let dst_stage_mask = dec.read_u32()?;
        let memory_barrier_count = dec.read_u32()?;
        let p_memory_barriers_sz = dec.read_array_size_unchecked()?;
        let mut p_memory_barriers = Vec::with_capacity(p_memory_barriers_sz as usize);
        for _ in 0..p_memory_barriers_sz { p_memory_barriers.push(VkMemoryBarrier::decode(dec)?); }
        let buffer_memory_barrier_count = dec.read_u32()?;
        let p_buffer_memory_barriers_sz = dec.read_array_size_unchecked()?;
        let mut p_buffer_memory_barriers = Vec::with_capacity(p_buffer_memory_barriers_sz as usize);
        for _ in 0..p_buffer_memory_barriers_sz { p_buffer_memory_barriers.push(VkBufferMemoryBarrier::decode(dec)?); }
        let image_memory_barrier_count = dec.read_u32()?;
        let p_image_memory_barriers_sz = dec.read_array_size_unchecked()?;
        let mut p_image_memory_barriers = Vec::with_capacity(p_image_memory_barriers_sz as usize);
        for _ in 0..p_image_memory_barriers_sz { p_image_memory_barriers.push(VkImageMemoryBarrier::decode(dec)?); }
        Ok(Self {
            command_buffer,
            event_count,
            p_events,
            src_stage_mask,
            dst_stage_mask,
            memory_barrier_count,
            p_memory_barriers,
            buffer_memory_barrier_count,
            p_buffer_memory_barriers,
            image_memory_barrier_count,
            p_image_memory_barriers,
        })
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>, flags: CommandFlags) -> Result<(), WireError> {
        enc.write_command_header(CommandHeader { cmd_type: VkCommandTypeEXT::VK_COMMAND_TYPE_vkCmdWaitEvents_EXT.0, flags })?;
        (self.command_buffer).encode(enc)?;
        enc.write_u32(self.event_count)?;
        enc.write_array_size(self.p_events.len() as u64)?;
        for item in &self.p_events { (*item).encode(enc)? }
        enc.write_u32(self.src_stage_mask)?;
        enc.write_u32(self.dst_stage_mask)?;
        enc.write_u32(self.memory_barrier_count)?;
        enc.write_array_size(self.p_memory_barriers.len() as u64)?;
        for item in &self.p_memory_barriers { (item).encode(enc)? }
        enc.write_u32(self.buffer_memory_barrier_count)?;
        enc.write_array_size(self.p_buffer_memory_barriers.len() as u64)?;
        for item in &self.p_buffer_memory_barriers { (item).encode(enc)? }
        enc.write_u32(self.image_memory_barrier_count)?;
        enc.write_array_size(self.p_image_memory_barriers.len() as u64)?;
        for item in &self.p_image_memory_barriers { (item).encode(enc)? }
        Ok(())
    }
}

