#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkExecuteCommandStreamsMESARequest {
    pub stream_count: u32,
    pub p_streams: Vec<VkCommandStreamDescriptionMESA>,
    pub p_reply_positions: Vec<u64>,
    pub dependency_count: u32,
    pub p_dependencies: Vec<VkCommandStreamDependencyMESA>,
    pub flags: VkCommandStreamExecutionFlagsMESA,
}

impl VkExecuteCommandStreamsMESARequest {
    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let stream_count = dec.read_u32()?;
        let p_streams_sz = dec.read_array_size_unchecked()?;
        let mut p_streams = Vec::with_capacity(p_streams_sz as usize);
        for _ in 0..p_streams_sz { p_streams.push(VkCommandStreamDescriptionMESA::decode(dec)?); }
        let p_reply_positions_sz = dec.read_array_size_unchecked()?;
        let mut p_reply_positions = Vec::with_capacity(p_reply_positions_sz as usize);
        for _ in 0..p_reply_positions_sz { p_reply_positions.push(dec.read_size_t()?); }
        let dependency_count = dec.read_u32()?;
        let p_dependencies_sz = dec.read_array_size_unchecked()?;
        let mut p_dependencies = Vec::with_capacity(p_dependencies_sz as usize);
        for _ in 0..p_dependencies_sz { p_dependencies.push(VkCommandStreamDependencyMESA::decode(dec)?); }
        let flags = dec.read_u32()?;
        Ok(Self {
            stream_count,
            p_streams,
            p_reply_positions,
            dependency_count,
            p_dependencies,
            flags,
        })
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>, flags: CommandFlags) -> Result<(), WireError> {
        enc.write_command_header(CommandHeader { cmd_type: VkCommandTypeEXT::VK_COMMAND_TYPE_vkExecuteCommandStreamsMESA_EXT.0, flags })?;
        enc.write_u32(self.stream_count)?;
        enc.write_array_size(self.p_streams.len() as u64)?;
        for item in &self.p_streams { (item).encode(enc)? }
        enc.write_array_size(self.p_reply_positions.len() as u64)?;
        for item in &self.p_reply_positions { enc.write_size_t(*item)? }
        enc.write_u32(self.dependency_count)?;
        enc.write_array_size(self.p_dependencies.len() as u64)?;
        for item in &self.p_dependencies { (item).encode(enc)? }
        enc.write_u32(self.flags)?;
        Ok(())
    }
}

